package com.thangit.boardinghouse.service;
import static org.assertj.core.api.Assertions.*;
import com.thangit.boardinghouse.dto.request.accountant.AccountantRequests.*;
import com.thangit.boardinghouse.service.FinanceWorkspaceService.Filter;
import com.thangit.boardinghouse.security.*;
import com.thangit.boardinghouse.domain.auth.RoleCode;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;

@EnabledIfSystemProperty(named="finance.workspace.mysql",matches="true")
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class FinanceWorkspaceMysqlTest {
 final ManagementFinanceMysqlTest b=new ManagementFinanceMysqlTest();FinanceWorkspaceService workspace;
 @BeforeAll void setup()throws Exception{b.setup();workspace=new FinanceWorkspaceService(b.f.db,b.service);}
 @BeforeEach void fixture(){b.fixture();}
 Filter filter(String tab){return new Filter(b.a.property(),b.start,b.end,tab,null,null,null,null,0,20);}
 Map<String,Object> get(String tab){return workspace.workspace(b.f.owner,filter(tab));}
 @SuppressWarnings("unchecked") List<Map<String,Object>> rows(Map<String,Object> data){return (List<Map<String,Object>>)data.get("rows");}
 BigDecimal money(Object v){return new BigDecimal(v.toString());}
 OtherIncomeCreate income(String amount,LocalDate when,String method){return new OtherIncomeCreate(b.a.property(),"OTHER_INCOME",b.n(amount),when,"Actual separate source",method,b.key());}
 @Test void ledgerOpeningAndClosingUseSameSourceBeforeFiltering(){b.f.run(()->workspace.income(b.f.owner,b.key(),income("500",b.start.minusDays(1),"CASH")));b.f.run(()->workspace.income(b.f.owner,b.key(),income("200",b.start,"CASH")));var data=get("cashbook");var ledger=(Map<?,?>)data.get("ledger");assertThat(money(ledger.get("opening"))).isEqualByComparingTo("500");assertThat(money(ledger.get("closing"))).isEqualByComparingTo("700");assertThat(ledger.get("verified")).isEqualTo(false);var r=rows(data).getFirst();assertThat(money(r.get("running_balance"))).isEqualByComparingTo("700");var f=filter("cashbook");var none=workspace.workspace(b.f.owner,new Filter(f.propertyId(),f.startDate(),f.endDate(),f.tab(),"no-match-xyz",null,null,null,0,20));assertThat(rows(none)).isEmpty();assertThat(none.get("ledger")).isEqualTo(ledger);}
 @Test void bankbookOnlyContainsManualBankSources(){b.f.run(()->workspace.income(b.f.owner,b.key(),income("100",b.start,"BANK_TRANSFER")));b.f.run(()->workspace.income(b.f.owner,b.key(),income("300",b.start,"CASH")));var data=get("bankbook");assertThat(rows(data)).hasSize(1);assertThat(rows(data).getFirst().get("verification")).isEqualTo("MANUAL_CONFIRMATION_NOT_BANK_RECONCILIATION");assertThat(data.get("bankIntegration")).isEqualTo(false);}
 @Test void invoiceReceiptIsProjectionAndDoesNotCollectAgain(){long i=b.invoice();b.pay(i,"3000000",b.key());long before=b.f.db.sql("SELECT COUNT(*) FROM payments WHERE invoice_id=:id").param("id",i).query(Long.class).single();assertThat(rows(get("receipts"))).hasSize(1);assertThat(rows(get("overview"))).hasSize(1);assertThat(b.f.db.sql("SELECT COUNT(*) FROM payments WHERE invoice_id=:id").param("id",i).query(Long.class).single()).isEqualTo(before);assertThat(b.totals().get("cashIn")).isEqualByComparingTo("3000000");}
 VoucherCreate request(){return new VoucherCreate(b.a.property(),"Supplier",b.n("2000000"),"REPAIR","CASH",LocalDate.now(),"Approved source evidence");}
 @Test void voucherCreationRetryIsIdempotentAndDraftIsNotCash(){String key=b.key();long id=((Number)b.f.inTx(()->workspace.createVoucher(b.f.accountant,key,request())).get("id")).longValue();assertThat(((Number)b.f.inTx(()->workspace.createVoucher(b.f.accountant,key,request())).get("id")).longValue()).isEqualTo(id);assertThat(b.totals().get("cashOut")).isZero();b.f.run(()->workspace.submit(b.f.accountant,id,0));assertThat(rows(get("vouchers")).getFirst().get("status")).isEqualTo("PENDING_APPROVAL");assertThat(b.totals().get("cashOut")).isZero();assertThatThrownBy(()->b.f.run(()->workspace.submit(b.f.accountant,id,0))).isInstanceOf(RuntimeException.class);}
 @Test void sameCreationKeyWithChangedAmountCannotCreateAnotherDraft(){String key=b.key();b.f.run(()->workspace.createVoucher(b.f.accountant,key,request()));assertThatThrownBy(()->b.f.run(()->workspace.createVoucher(b.f.accountant,key,new VoucherCreate(b.a.property(),"Supplier",b.n("1"),"REPAIR","CASH",LocalDate.now(),"Different")))).isInstanceOf(RuntimeException.class);assertThat(rows(get("vouchers"))).hasSize(1);}
 @Test void operatingCostAndActualPaymentAreSeparate(){long v=b.voucher("REPAIR");b.submit(v);b.approve(v);var expense=rows(get("expenses")).getFirst();assertThat(money(expense.get("paid_amount"))).isZero();assertThat(money(expense.get("payable"))).isEqualByComparingTo("2000000");assertThat(rows(get("cashbook"))).isEmpty();b.paid(v);expense=rows(get("expenses")).getFirst();assertThat(money(expense.get("paid_amount"))).isEqualByComparingTo("2000000");assertThat(money(expense.get("payable"))).isZero();assertThat(rows(get("cashbook"))).hasSize(1);}
 @Test void incomeRetryDoesNotDuplicateAndPrepaymentIsNotRent(){var r=new OtherIncomeCreate(b.a.property(),"PREPAYMENT",b.n("200"),b.start,"Actual prepayment","CASH",b.key());String key=b.key();b.f.run(()->workspace.income(b.f.owner,key,r));b.f.run(()->workspace.income(b.f.owner,key,r));assertThat(rows(get("receipts"))).hasSize(1);assertThat(b.totals().get("customerAdvances")).isEqualByComparingTo("200");assertThat(b.totals().get("serviceCashIn")).isZero();}
 @Test void wrongRoleAndOtherOwnerCannotReadOrExport(){var other=new AuthenticatedUser(2L,"other",RoleCode.OWNER);assertThatThrownBy(()->workspace.workspace(other,filter("cashbook"))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->workspace.export(other,filter("receipts"))).isInstanceOf(RuntimeException.class);assertThatThrownBy(()->workspace.workspace(b.f.tenant,filter("overview"))).isInstanceOf(RuntimeException.class);}
 @Test void accountantWithoutAssignmentCannotCreate(){b.f.db.sql("DELETE FROM accountant_property_assignments WHERE accountant_id=4 AND property_id=:id").param("id",b.a.property()).update();assertThatThrownBy(()->b.f.run(()->workspace.createVoucher(b.f.accountant2,b.key(),request()))).isInstanceOf(RuntimeException.class);assertThat(rows(get("vouchers"))).isEmpty();}
 @Test void invalidExpenseSourceRollsBackDraft(){var r=new VoucherCreate(b.a.property(),"Supplier",b.n("2000000"),"REPAIR","CASH",LocalDate.now(),"Invalid link",999999999L);assertThatThrownBy(()->b.f.run(()->workspace.createVoucher(b.f.accountant,b.key(),r))).isInstanceOf(RuntimeException.class);assertThat(rows(get("vouchers"))).isEmpty();}
 @Test void filtersPaginationAndExcelHaveSameCohort(){b.f.run(()->workspace.income(b.f.owner,b.key(),income("100",b.start,"CASH")));var f=filter("receipts");byte[] all=workspace.export(b.f.owner,f);assertThat(all[0]).isEqualTo((byte)'P');assertThat(all[1]).isEqualTo((byte)'K');var none=workspace.workspace(b.f.owner,new Filter(f.propertyId(),f.startDate(),f.endDate(),f.tab(),null,null,"SERVICE_COLLECTION",null,0,20));assertThat(rows(none)).isEmpty();assertThat(((Number)none.get("totalElements")).longValue()).isZero();}
 @Test void organizationFilterCannotGrantPropertyAccess(){var f=filter("overview");var empty=workspace.workspace(b.f.owner,new Filter(f.propertyId(),f.startDate(),f.endDate(),f.tab(),null,null,null,null,0,20,9999999L,null));assertThat(rows(empty)).isEmpty();assertThat(money(((Map<?,?>)empty.get("summary")).get("cashIn"))).isZero();}
 @Test void periodsAndReconciliationReadExistingState(){b.period();var check=b.f.inTx(()->b.reconciliation.run(1,b.a.property(),b.start,b.end));assertThat(rows(get("periods"))).hasSize(1);assertThat(rows(get("reconciliation"))).hasSize(1);assertThat(check.get("automaticRepair")).isEqualTo(false);}
 @Test void closedPeriodRejectsIncomeWithoutChangingCash(){long id=b.period();b.f.run(()->b.accounting.closePeriod(b.f.accountant,id,new PeriodAction(0,"Verified sources")));assertThatThrownBy(()->b.f.run(()->workspace.income(b.f.owner,b.key(),income("100",b.start,"CASH")))).isInstanceOf(RuntimeException.class);assertThat(rows(get("cashbook"))).isEmpty();}
 @Test void reversalRetainsSourceAndAuditAndCannotBeAppliedTwice(){long id=((Number)b.f.inTx(()->workspace.income(b.f.owner,b.key(),income("100",b.start,"CASH"))).get("id")).longValue();assertThatThrownBy(()->b.f.run(()->workspace.reverseIncome(b.f.accountant,id,"No approval"))).isInstanceOf(RuntimeException.class);b.f.run(()->workspace.reverseIncome(b.f.owner,id,"Incorrect separate collection"));assertThat(b.f.db.sql("SELECT status FROM other_income WHERE id=:id").param("id",id).query(String.class).single()).isEqualTo("REVERSED");assertThat(rows(get("cashbook"))).isEmpty();assertThat(rows(get("history")).stream().anyMatch(r->"REVERSED".equals(r.get("status")))).isTrue();assertThatThrownBy(()->b.f.run(()->workspace.reverseIncome(b.f.owner,id,"Repeated"))).isInstanceOf(RuntimeException.class);}
 @Test void concurrentVoucherCreationUsesOneDraft()throws Exception{String key=b.key();var r=request();var latch=new java.util.concurrent.CountDownLatch(1);try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var x=pool.submit(()->{latch.await();return b.f.inTx(()->workspace.createVoucher(b.f.accountant,key,r)).get("id");});var y=pool.submit(()->{latch.await();return b.f.inTx(()->workspace.createVoucher(b.f.accountant,key,r)).get("id");});latch.countDown();assertThat(x.get(20,java.util.concurrent.TimeUnit.SECONDS)).isEqualTo(y.get(20,java.util.concurrent.TimeUnit.SECONDS));}assertThat(rows(get("vouchers"))).hasSize(1);}
 @Test void depositExportUsesCurrentDepositSourcesInsteadOfCashEvents()throws Exception{var data=get("deposits");assertThat(rows(data)).isNotEmpty();assertThat(rows(data).getFirst()).containsKeys("required_amount","received_amount","balance_amount","remaining_deposit_due");byte[] bytes=workspace.export(b.f.owner,filter("deposits"));String sheet="";try(var zip=new java.util.zip.ZipInputStream(new java.io.ByteArrayInputStream(bytes))){java.util.zip.ZipEntry part;while((part=zip.getNextEntry())!=null){if(part.getName().equals("xl/worksheets/sheet1.xml"))sheet=new String(zip.readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}}assertThat(sheet).contains("Đã nhận hợp lệ","Đang giữ").doesNotContain("Tiền vào","Tiền ra");}
 @Test void voucherActionsReflectAccountantPermissions(){long id=b.voucher("REPAIR");b.f.db.sql("UPDATE accountant_profiles SET can_record_payment=FALSE WHERE user_id=3").update();try{var data=workspace.workspace(b.f.accountant,filter("vouchers"));assertThat(rows(data).getFirst().get("canPay")).isEqualTo(false);assertThat(rows(data).getFirst().get("canApprove")).isEqualTo(false);}finally{b.f.db.sql("UPDATE accountant_profiles SET can_record_payment=TRUE WHERE user_id=3").update();}}
}
